INSERT INTO products (id, name, category, categoryId, price, originalPrice, rating, reviewCount, image, images, description, features, specifications, sizes, colors, inStock, isBestseller, isNew, createdAt, updatedAt) VALUES ('0fab039e-83d2-4d9d-bbc0-f6278168b219', 'High quality american football gloves design your own football gloves', 'Football Gloves', 'football-gloves', '7.54', '36.0', '0', '0', 'https://www.sellgloves.com/uploadfile/upload/2019022216241977.jpg', '["https://www.sellgloves.com/uploadfile/upload/2019022216241977.jpg", "https://www.sellgloves.com/uploadfile/upload/2020042617200422.jpg", "https://www.sellgloves.com/uploadfile/upload/2020061016412292.jpg", "https://www.sellgloves.com/uploadfile/upload/2020090116025815.jpg"]', 'Breathable, flexible mesh back helps keep you cool. Mesh knuckles let your fingers flex naturally for more control. Adjustable closure for a custom fit. Full-length silicone palm provides a supreme grip. Product Type: American football gloves Material: silicone, Fabric Type: Pigue Technics: Embroidered Feature: Eco-Friendly, Water Soluble, Other Decoration: Sequins Color: White Width: 120cm FAQ 1,Are receivers gloves sticky? Sticky gloves are permitted, provided that "such tacky substance does not adhere to the football or otherwise cause handling problems for players." 2,How can I make my football gloves sticky again? Before each game, take a wipe, either a Clorox wipe or baby wipe, and wipe down your gloves . The easiest way to do this it to put on your gloves , roll-up a wipe, and rub it between your gloved-palms. Make sure to get the fingers. Then rub your gloves together and you should begin to feel them getting grippier.', '[]', '{"Material": "Pigue,silicone", "Size": "Custom Size", "Color": "White", "Logo": "Embroidery,printing,plastic label or customized", "Packaging": "Opp bag", "Sample Time": "7-14 work days", "OEM": "Acceptable", "Function": "Hand Protection", "Model No.": "High quality american football gloves05"}',